// PartitionSpecification defines the format of partition filtering
// specification for shared tables. It consists of a list of Partitions which in
// turn include a list of PartitionValues. - Partitions inside a single
// PartitionSpecification have OR logical relationship. - PartitionValues inside
// a single Partition have AND logical relationship. - PartitionValue.name must
// have distinct values inside a single Partition..
type PartitionSpecification struct {
}

type PartitionSpecification_Partition struct {
	// An array of partition values.
	Values []PartitionSpecification_Partition_PartitionValue
}

type PartitionSpecification_Partition_PartitionValue struct {
	// The name of the partition column.
	Name *string
	// The value of the partition column. When this value is not set, it means
	// `null` value. When this field is set, field `recipient_property_key` can not
	// be set.
	Value *string
	// The key of a Delta Sharing recipient's property. For example
	// "databricks-account-id". When this field is set, field `value` can not be
	// set.
	RecipientPropertyKey *string
	// The operator to apply for the value.
	Op PartitionSpecification_Partition_PartitionValue_PartitionValueOp
}

